      "path": "benchmark/writing/method.json",
      "locator": "/tasks/4/trial_artifacts/manifest_rule",
      "value": "Freeze original file set and dependencies before exposure. Only task.output_path may differ. Preserve immutable originals outside writable roots and reject cross-arm/original dependency resolution. A manifest or patch is not a substitute for complete artifact bytes.",
