for i,e in enumerate(p["examples"]):
 invrows=[]
 for name,inv in e["inventories"].items():
  entries=inv["entries"]; er=[]
  for entry in entries:
   obj=raw[entry["byte_object"]]; er.append({"path":entry["path"],"fields":sorted(entry),"size_hash_match":(entry["size"],entry["sha256"])==(len(obj),h(obj)),"raw_reference_match":entry["raw_byte_reference"]=={"path":"benchmark/writing/wp1-examples-0121.json","locator":"/byte_objects/"+entry["byte_object"]}})
  refs=inv.get("declared_references",[]); checks=[]
  for ref in refs:
   loc=ref["declaration"]["locator"]; node=root
   for part in loc.split(":",1)[1].split("/")[1:-1]: node=node[int(part)]
   checks.append(node.attrib["URL"]==ref["path"]==ref["declaration"]["value"] and ref["status"]=="unavailable" and all(ref[x] is None for x in ["size","sha256","raw_byte_reference"]) and bool(ref["reason"]))
  invrows.append({"name":name,"fields":sorted(inv),"count":len(entries),"count_matches":inv["file_count"]==len(entries),"entries_hash_matches":inv["entries_sha256"]==h(canon(entries)),"entries":er,"reference_count":len(refs),"reference_list_matches_cold":not refs or [r["path"] for r in refs]==[r["url"] for r in c["declared_url_references"]],"all_declaration_locators_and_unavailable_statuses_match":all(checks)})
 rows.append({"index":i,"id":e["id"],"inventories":invrows,"map_ids_match": [r["id"] for r in e["original_output_map"]]==c["semantic_ids"]+c["preservation_ids"],"trial_categories_match": [r["id"] for r in e["trial_artifact_accounting"]]==c["inventory_expectation"]["trial_artifact_categories"]})
print(json.dumps({"output":{"bytes":len(out),"sha256":h(out),"matches_cold":(len(out),h(out))==(c["expected_output"]["bytes"],c["expected_output"]["sha256"]),"changed_offsets":[i for i,(x,y) in enumerate(zip(b,out)) if x!=y],"complement_identical":b[:3347]==out[:3347] and b[3348:]==out[3348:],"root_attributes_unchanged":root.attrib==E.fromstring(out).attrib,"autoIncrement_line_33":b.decode("utf-8-sig").splitlines()[32]},"required_ids_match_cold":all(p["required_ids"][k]==c[k] for k in ["semantic_ids","preservation_ids","answer_ids"]),"requirement_count":len(p["requirement_inventory"]),"protected_pin_count":len(p["protected_pins"]),"examples":rows},indent=2))'

